  1430→        dotsEl.innerHTML = '';
  1431→        if (!mq.matches) return;
  1432→        const cards = Array.from(grid.children);
  1433→        cards.forEach((_, i) => {
  1434→            const btn = document.createElement('button');
  1435→            btn.className = 'mcd' + (i === 0 ? ' active' : '');
  1436→            btn.setAttribute('aria-label', 'Slide ' + (i + 1));
  1437→            btn.addEventListener('click', () => {
  1438→                grid.scrollTo({ left: cards[i].offsetLeft - grid.offsetLeft, behavior: 'smooth' });
  1439→            });
  1440→            dotsEl.appendChild(btn);
  1441→        });
  1442→    }
  1443→    function updateDots() {
  1444→        if (!mq.matches) return;
  1445→        const cards = Array.from(grid.children);
  1446→        const gap   = parseFloat(getComputedStyle(grid).gap) || 16;
  1447→        const cardW = (cards[0]?.offsetWidth || 1) + gap;
  1448→        const idx   = Math.min(Math.round(grid.scrollLeft / cardW), cards.length - 1);
  1449→        dotsEl.querySelectorAll('.mcd').forEach((d, i) => d.classList.toggle('active', i === idx));
  1450→    }
  1451→    grid.addEventListener('scroll', updateDots, { passive: true });
  1452→    mq.addEventListener('change', buildDots);
  1453→    buildDots();
  1454→}
