  1408→/* ── Count-up ── */
  1409→function countUp(el) {
  1410→    const target = parseInt(el.dataset.target, 10);
  1411→    if (!target) return;
  1412→    const exact  = el.dataset.exact === '1';
  1413→    const suffix = (!exact && target > 0) ? '+' : '';
  1414→    const duration = 1600;
  1415→    const step = target / (duration / 16);
  1416→    let current = 0;
  1417→    const timer = setInterval(() => {
  1418→        current = Math.min(current + step, target);
  1419→        el.textContent = Math.floor(current) + suffix;
  1420→        if (current >= target) clearInterval(timer);
  1421→    }, 16);
  1422→}
  1423→const countObs = new IntersectionObserver((entries) => {
  1424→    entries.forEach(e => {
  1425→        if (e.isIntersecting) { countUp(e.target); countObs.unobserve(e.target); }
  1426→    });
  1427→}, { threshold: 0.5 });
  1428→document.querySelectorAll('.count-up[data-target]').forEach(el => countObs.observe(el));
