  1446→function initMobileCarousel(gridId, dotsId) {
  1447→    const grid   = document.getElementById(gridId);
  1448→    const dotsEl = document.getElementById(dotsId);
  1449→    if (!grid || !dotsEl) return;
  1450→    const mq = window.matchMedia('(max-width:640px)');
  1451→    function buildDots() {
  1452→        dotsEl.innerHTML = '';
  1453→        if (!mq.matches) return;
  1454→        const cards = Array.from(grid.children);
  1455→        cards.forEach((_, i) => {
  1456→            const btn = document.createElement('button');
  1457→            btn.className = 'mcd' + (i === 0 ? ' active' : '');
  1458→            btn.setAttribute('aria-label', 'Slide ' + (i + 1));
  1459→            btn.addEventListener('click', () => {
  1460→                const pl = parseFloat(getComputedStyle(grid).paddingLeft) || 0;
  1461→                grid.scrollTo({ left: Math.max(0, cards[i].offsetLeft - pl), behavior: 'smooth' });
  1462→            });
  1463→            dotsEl.appendChild(btn);
  1464→        });
  1465→    }
  1466→    function updateDots() {
  1467→        if (!mq.matches) return;
  1468→        const cards = Array.from(grid.children);
  1469→        const gap   = parseFloat(getComputedStyle(grid).gap) || 16;
  1470→        const cardW = (cards[0]?.offsetWidth || 1) + gap;
  1471→        const idx   = Math.min(Math.round(grid.scrollLeft / cardW), cards.length - 1);
  1472→        dotsEl.querySelectorAll('.mcd').forEach((d, i) => d.classList.toggle('active', i === idx));
  1473→    }
  1474→    grid.addEventListener('scroll', updateDots, { passive: true });
  1475→    mq.addEventListener('change', buildDots);
  1476→    buildDots();
  1477→}
