  3829→window.countUpValue = function(el, target) {
  3830→    if (!el) return;
  3831→    const num = parseInt(target, 10);
  3832→    if (isNaN(num) || num < 0) { el.textContent = target; return; }
  3833→    const duration = 600;
  3834→    const step = 14;
  3835→    const increment = Math.max(1, num / (duration / step));
  3836→    let current = 0;
  3837→    clearInterval(el._countTimer);
  3838→    el._countTimer = setInterval(function() {
  3839→        current += increment;
  3840→        if (current >= num) { current = num; clearInterval(el._countTimer); }
  3841→        el.textContent = Math.floor(current).toLocaleString('id-ID');
  3842→    }, step);
