  3864→    const observer = new IntersectionObserver((entries) => {
  3865→        entries.forEach((entry, idx) => {
  3866→            if (entry.isIntersecting) {
  3867→                // Stagger siblings with same parent
  3868→                const siblings = entry.target.parentElement
  3869→                    ? Array.from(entry.target.parentElement.children).filter(el => el.classList.contains('fade-up'))
  3870→                    : [];
  3871→                const sibIdx = siblings.indexOf(entry.target);
  3872→                const delay = sibIdx >= 0 ? sibIdx * 0.05 : 0;
  3873→                setTimeout(() => entry.target.classList.add('in-view'), delay * 1000);
  3874→                observer.unobserve(entry.target);
  3875→            }
  3876→        });
  3877→    }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
  3878→    allFadeUps.forEach(el => observer.observe(el));
